-- ---------------------------------------------------------------- messages
CREATE TEMP TABLE stg_messages (LIKE public.messages INCLUDING DEFAULTS) ON COMMIT DROP;
\copy stg_messages FROM 'migration-data/messages.csv' WITH (FORMAT csv, HEADER true)

CREATE TEMP TABLE ok_messages ON COMMIT DROP AS
  SELECT s.* FROM stg_messages s
  WHERE
    (s.conversation_id IS NULL OR EXISTS (SELECT 1 FROM public.conversations p WHERE p.id = s.conversation_id))
    AND
    (s.sender_id IS NULL OR EXISTS (SELECT 1 FROM auth.users p WHERE p.id = s.sender_id));
UPDATE ok_messages SET reply_to = NULL;  -- self-reference restored below

WITH ins AS (
  INSERT INTO public.messages SELECT * FROM ok_messages ON CONFLICT DO NOTHING RETURNING 1
)
INSERT INTO public._migration_report
  (table_name, csv_rows, importable_rows, inserted, skipped_orphan, skipped_conflict)
SELECT 'messages',
       (SELECT count(*) FROM stg_messages),
       (SELECT count(*) FROM ok_messages),
       (SELECT count(*) FROM ins),
       (SELECT count(*) FROM stg_messages) - (SELECT count(*) FROM ok_messages),
       (SELECT count(*) FROM ok_messages) - (SELECT count(*) FROM ins);

-- restore messages.reply_to now that all rows exist
UPDATE public.messages t
   SET reply_to = s.reply_to
  FROM stg_messages s
 WHERE t.id = s.id
   AND s.reply_to IS NOT NULL
   AND EXISTS (SELECT 1 FROM public.messages p WHERE p.id = s.reply_to);

-- soft check: messages rows pointing at a user id that has no auth account
INSERT INTO public._migration_orphans (table_name, column_name, missing_count)
SELECT 'messages', c.col, c.n FROM (
  SELECT 'sender_id'::text AS col, count(*)::int AS n FROM public.messages x
    WHERE x.sender_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = x.sender_id)
) c WHERE c.n > 0;

